files.content:
:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --accent: #f0c040;
  --accent-dark: #c9a020;
  --text: #e8e8f0;
  --text-muted: #a0a0b8;
  --heads: #4caf50;
  --tails: #e57373;
  --focus: #f0c040;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 12px;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  border: 2px solid var(--accent-dark);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 24px;
  color: var(--accent);
  letter-spacing: 1px;
}

.coin-container {
  margin-bottom: 16px;
  display: flex;
  justify-content: center;
}

.coin {
  width: 120px;
  height: 120px;
  position: relative;
  transform-style: preserve-3d;
  transition: transform 0.6s ease;
}

.coin-face {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  font-weight: bold;
  border-radius: 50%;
  backface-visibility: hidden;
  border: 4px solid var(--accent-dark);
  image-rendering: pixelated;
}

.coin-heads {
  background: var(--accent);
  color: var(--bg);
  transform: rotateY(0deg);
}

.coin-tails {
  background: var(--accent-dark);
  color: var(--bg);
  transform: rotateY(180deg);
}

.coin.show-tails {
  transform: rotateY(180deg);
}

.result {
  font-size: 1.25rem;
  margin-bottom: 24px;
  min-height: 1.5em;
  color: var(--text-muted);
  font-weight: 600;
}

.stats {
  display: flex;
  justify-content: space-around;
  gap: 8px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  min-width: 80px;
}

.stat-label {
  font-size: 0.875rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.stat-value {
  font-size: 1.75rem;
  font-weight: bold;
  color: var(--accent);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 28px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  min-width: 120px;
}

.btn-flip {
  background: var(--accent);
  color: var(--bg);
}

.btn-flip:hover {
  background: var(--accent-dark);
}

.btn-flip:active {
  transform: scale(0.96);
}

.btn-reset {
  background: transparent;
  color: var(--text-muted);
  border: 2px solid var(--text-muted);
}

.btn-reset:hover {
  background: var(--text-muted);
  color: var(--bg);
}

.btn-reset:active {
  transform: scale(0.96);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .coin {
    width: 100px;
    height: 100px;
  }
  .coin-face {
    font-size: 2.5rem;
  }
  .btn {
    min-width: 100px;
    padding: 12px 20px;
  }
}

(function () {
  'use strict';

  var coin = document.getElementById('coin');
  var resultEl = document.getElementById('result');
  var headsEl = document.getElementById('heads-count');
  var tailsEl = document.getElementById('tails-count');
  var streakEl = document.getElementById('streak');
  var flipBtn = document.getElementById('flip-btn');
  var resetBtn = document.getElementById('reset-btn');

  var heads = 0;
  var tails = 0;
  var streak = 0;
  var lastSide = null;
  var flipping = false;

  function updateDisplay() {
    headsEl.textContent = heads;
    tailsEl.textContent = tails;
    streakEl.textContent = streak;
  }

  function flip() {
    if (flipping) return;
    flipping = true;

    var side = Math.random() < 0.5 ? 'heads' : 'tails';

    // Animation: briefly toggle class
    coin.classList.toggle('show-tails', side === 'tails');

    // Update counts
    if (side === 'heads') {
      heads++;
      if (lastSide === 'heads') {
        streak++;
      } else {
        streak = 1;
      }
    } else {
      tails++;
      if (lastSide === 'tails') {
        streak++;
      } else {
        streak = 1;
      }
    }
    lastSide = side;

    resultEl.textContent = side === 'heads' ? 'Heads!' : 'Tails!';
    updateDisplay();

    // Allow next flip after animation
    setTimeout(function () {
      flipping = false;
    }, 600);
  }

  function reset() {
    heads = 0;
    tails = 0;
    streak = 0;
    lastSide = null;
    flipping = false;
    coin.classList.remove('show-tails');
    resultEl.textContent = 'Flip the coin!';
    updateDisplay();
  }

  flipBtn.addEventListener('click', flip);
  resetBtn.addEventListener('click', reset);

  // Initial display
  updateDisplay();
})();
